INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'e840ed1f-528a-4ce6-9acb-2247d2d241e6',N'Umineko no Naku Koro ni Chiru - Episode 8: Twilight of the Golden Witch',N'It''s time once again for the annual family gathering on Rokkenjima! Ange Ushiromiya is just getting over a cold, but that won''t dampen her excitement at seeing her cousins again! Granddad couldn''t be more thrilled to see his beloved grandchildren and throws a special Halloween party where everyone gets lots of treats! By lunchtime on the first day, the aunts and uncles are chatting up a storm, and the cousins are eagerly planning the afternoon''s fun. It''s the very picture of a happy family-one that in no way resembles the bickering, bitter Ushiromiya clan! What is going on?!  ( Press)',1,3,2,112,1,N'd74e7a6c-e56e-4b92-b8d9-17f7aabaae21',NULL,'2026-01-30 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
