INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'b8ed0ecc-164e-416c-9d1f-ef710822ecaf',N'20th Century Boys',N'As the 20th century approaches its end, people all over the world are anxious that the world is changing. And probably not for the better. Kenji Endou is a normal convenience store manager who is just trying to get by. But when he learns that one of his old friends going by the name "Donkey" has suddenly committed suicide and that a new cult led by a figure known as "Friend" is becoming more notorious, Kenji starts to feel that something is not right. With a few key clues left behind by his deceased friend, Kenji realizes that this cult is much more than he ever thought it would be—not only is this mysterious organization directly targeting him and his childhood friends, but the whole world also faces a grave danger that only the friends have the key to stop. Kenji''s simple life of barely making ends meet is flipped upside down when he reunites with his childhood friends, and together they must figure out the truth of how their past is connected to the cult, as the turn of the century could mean the possible end of the world.',1,3,2,112,1,N'1070b1f8-539d-4eeb-92b3-e1c596e9a2b4',NULL,'2026-02-20 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
