INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'58ffaaf8-e938-4e79-bd1f-628767c9d440',N'3-gatsu no Lion',N'Rei Kiriyama is an extraordinary shogi player. Among the few elites to have gone professional as a middle school student, he is considered a genius. But what lies behind his prodigious facade is a teenage boy who suffers immense pressure from both his family and from the high expectations from the shogi community. Rei moves out to live a more independent life away from his family, but his unorganized lifestyle and unsociable personality show no signs of improvement. However, in a twist of fate that will prove to be a turning point in his life, Rei encounters the Kawamoto sisters—the motherly Akari, the passionate Hinata, and the energetic Momo—who take great care of him. 3-gatsu no Lion tells the story of Rei as he reshapes his melancholic life and picks up the courage to begin facing the problems he evaded during his past.',1,1,2,112,1,N'e9714cdd-5658-4cfd-9fef-22fd590d8265',NULL,'2026-03-01 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
