INSERT INTO [dbo].[MangaSeason] ([Id],[Season],[Description],[CreateDate],[IdUserCreate]) VALUES (N'7177bbb9-7597-4ba2-b0dc-f21527eac8e5',1.0,N'Season 1','2026-03-07 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'0d89e2e2-b846-4766-b300-7e39438c4d8b',N'Haikyuu!!',N'The whistle blows. The ball is up. A dig. A set. A spike. Volleyball. A sport where two teams face off, separated by a formidable, wall-like net. The "Little Giant," standing at only 170 centimeters, overcomes the towering net and the wall of blockers. The awe-inspired Shouyou Hinata looks on at the ace''s crow-like figure. Determined to reach great heights like the Little Giant, small-statured Hinata finally manages to form a team in his last year of junior high school, and enters his first volleyball tournament. However, his team is utterly defeated in their first game against the powerhouse school Kitagawa Daiichi, led by the genius, but oppressive setter dubbed the "King of the Court," Tobio Kageyama. Hinata enrolls into Karasuno High School seeking to take revenge against Kageyama in an official high school match and to follow in the Little Giant''s footsteps—but his plans are ruined when he opens the gymnasium door to find Kageyama as one of his teammates. Now, Hinata must establish himself on the team and work alongside the problematic Kageyama to overcome his shortcomings and to fulfill his dream of making it to the top of the high school volleyball world. Included one-shot: Volume 14: Nisekyuu!!',1,3,2,112,1,N'7177bbb9-7597-4ba2-b0dc-f21527eac8e5',NULL,'2026-03-07 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
