INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'6fa84bd4-18ec-4754-904d-20acb95a230e',N'Medalist',N'Becoming an ice dancer was not what Tsukasa Akeuraji had aimed for when he decided to take on the figure skating world. However, it is where he ended up, as he "started too late" to follow his true solo-skating dreams. For years, he was content with being a shell of his former ambitions—that is, until he met a little girl in whom he saw himself. Inori Yuitsuka, a fifth-grader so desperate to skate that she practiced in secret, had visited Tsukasa''s rink with her mother to ask for lessons. She was branded as useless by everyone around her, told it was "too late" for her to begin, and that catching up to other skaters was impossible. With a newfound conviction and unwillingness to let another passionate skater go down the same road as him, Tsukasa takes on the responsibility of coaching her and promises to make Inori a medalist.',1,1,2,112,1,N'dc519a7c-e17c-4681-ba61-3a994a544366',NULL,'2026-03-10 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
