INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'a0b0edac-546a-4ace-a7e7-fac507c9abae',N'Kokou no Hito',N'Through pain and arduous effort, one can reach the top of the world. Standing where no man has ever set foot before, there is an exhilarating feeling of success. This is what Mori Buntarou trains, works, and lives for. His climb to the top starts when he transfers to a new high school. Despite his lonesome and solitary nature, Mori''s classmates persuade him to climb the school building. Without a harness or hesitation, he begins his scale to reach the top. Edging past the point of no return, he halts when he is faced with a final intimidating obstacle—a horizontal overhang. Adrenaline courses through him, and Mori jumps for the final hold at the summit. From there, he casts his eyes upon something that he normally would not have seen—another peak, another goal. With an awakened passion and newfound purpose in life, Mori explores the breathtaking sport of rock climbing.',1,3,2,112,1,N'e18f9ea5-e23c-430a-a8c4-969e3b6bfd64',NULL,'2026-03-16 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
