INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'fe6ea809-c388-471f-a1fd-5ddba81c220e',N'Veil',N'On a cold and silent day, a man and a woman meet. He is Aleksander, a police officer, and she is Emma, a young, blind woman who has fled her home in search of independence. As it happens, Aleksander''s station needs someone to take calls. They make an unlikely pair—a small, stylish woman and a tall, intimidating man—but something tentative and intimate blossoms between them, resembling neither friendship nor love, as if a thin, transparent veil is raised between them.',1,1,2,112,1,N'34c91955-dd45-43e1-9d37-ca59eaaa2e5a',NULL,'2026-03-19 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
