INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'ee3441ca-5d44-4d76-8ea9-378fb1c83f50',N'Kaze no Tani no Nausicaä',N'Humanity, once a technologically advanced and thriving civilization, has been pushed to the brink of extinction following a cataclysmic war known as the Seven Days of Fire. The remnants of the human race now live in scattered kingdoms to avoid the unrelenting spread of the Sea of Corruption, a colossal forest infested with dangerous mutant insects and fungi that produce poisonous spores. Nausicaä, the sole heir to the throne of the agricultural kingdom Valley of the Wind, is thrust into war after an ally kingdom, the imperialist Torumekia, invades the Dorok Empire. Forced to fight alongside the Torumekian military and their cunning princess Kushana, Nausicaä witnesses firsthand the horrors of war and its effect on both humanity and the environment. With her uncanny charisma and gentle nature, Nausicaä may be the only hope for humanity as the ongoing war and the Sea of Corruption hasten the extinction of mankind. Set against the backdrop of a devastated world, Kaze no Tani no Nausicaä depicts the aftermath of human folly and the immortal power of nature.',1,3,2,112,1,N'a0fda8b0-4d31-482c-8a39-795a50c7aa8f',NULL,'2026-03-22 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
