INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'8d75509f-2bc8-4906-9aab-00ea84bc0ca0',N'Uchuu Kyoudai',N'"A big brother must always stay ahead of his younger brother. That is my responsibility as the older sibling"—these are the words that have always motivated Mutta Nanba to try his best when it came to his younger brother, Hibito. So naturally, in the summer of 2006 when the Nanba brothers witness something strange in the night sky, Hibito declared that he would become an astronaut and travel to the Moon, while Mutta countered with the affirmation that he would go to Mars. That was the promise they made to each other. Now in 2025, while Hibito is working with NASA and preparing to become the first Japanese to land on the moon, Mutta has been fired from his job in an automotive development company. Having difficulty finding another job, Mutta is given a lifetime opportunity when he receives a letter from JAXA—the Japan Aerospace Exploration Agency—telling him that he has been accepted to participate in the next astronaut selection. As if fate has given him a chance to fulfill the promise he made all those years ago, Mutta undertakes the difficult challenge of going to space.',1,1,2,112,1,N'd637515b-57f5-499b-9676-38be88acfdf3',NULL,'2026-04-03 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
