INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'ef1a2d50-c5b3-44ee-960f-d2cdd0459090',N'Hunter x Hunter',N'"Secret treasure hoards, undiscovered wealth... mystical places, unexplored frontiers... ''The mysterious unknown.'' There''s magic in such words for those captivated by its spell. They are called ''Hunters''!" Gon Freecss wants to become a Hunter so he can find his father, a man who abandoned him to pursue a life of adventure. But it''s not that simple: only one in one hundred thousand can pass the Hunter Exam, and that is just the first obstacle on his journey. During the Hunter Exam, Gon befriends many other potential Hunters, such as the mysterious Killua; the revenge-driven Kurapika; and Leorio, who aims to become a doctor. There''s a world of adventure and peril awaiting, and those who embrace it with open arms can become the greatest Hunters of them all!',1,1,2,112,1,N'14f5c97a-304f-435f-bfbf-bce50718f684',NULL,'2026-04-15 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
