INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'ab01db4f-78e5-420c-a470-f2f2293150a9',N'Jumyou wo Kaitotte Moratta. Ichinen ni Tsuki, Ichimanen de.',N'Helpless and struggling for cash, 20-year-old Kusunoki sells the last of his possessions to buy food. Noticing his poverty, an old shop owner directs him to a store that supposedly purchases lifespan, time, and health. While not completely believing the man''s words, Kusunoki nevertheless finds himself at the address out of desperation and curiosity. Kusunoki is crushed when he finds out the true monetary value of his lifespan—totaling a meager three hundred thousand yen. Deciding to sell the next 30 years of his life for ten thousand yen per year, Kusunoki is left with only three months to live. After heading home with the money, he is greeted by an unexpected visitor: the same store clerk he sold his lifespan to. She introduces herself as Miyagi, the one tasked with the job of observing him until the last three days of his life. Jumyou wo Kaitotte Moratta. Ichinen ni Tsuki, Ichimanen de. follows the remaining three months of Kusunoki''s life as he confronts lingering regrets from the past and discovers what truly gives life value.',1,3,2,112,1,N'b33d0fa7-fc21-43eb-a33a-6ba26ba1278b',NULL,'2026-04-18 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
