INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'a7f18fc6-f13f-4871-a61a-7dc6be0d8264',N'Umineko no Naku Koro ni Chiru - Episode 7: Requiem of the Golden Witch',N'The time for logical debate and magical feints has come to an end; the revelation of the truth about Beatrice the Golden Witch is at hand. To facilitate this, game master Bernkastel has chosen Will Wright the Mage-Hunter to step onto her board and answer a single question: Who killed Beatrice? Joining him in the game is Lion Ushiromiya, Krauss''s firstborn and heir, whose role is a mystery in its own right. Will''s line of questioning draws together the stray strands from all the previous games, twisting them into a thread of truth, revisiting Kinzou''s first encounter with the young Beatrice and working through the legends that have since sprung up around her... ( Press)',1,3,2,112,1,N'89af35e5-31d7-4e89-896c-06febc581a2d',NULL,'2026-04-21 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
