INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate]) VALUES (N'edd2db16-95ff-4e15-a455-1b72fc84195e',N'Kimi to Tsuzuru Utakata',N'The self-conscious Shizuku Hoshikawa is on her way to dispose of her first and last novel. But before she can do so, the charismatic Kaori Asaka bumps into her and ends up taking the novel home. This turn of events greatly distresses Shizuku, as she does not want anyone to read the depressing story she wrote for her own satisfaction. Initially expecting the worst, Shizuku finds herself in tears of joy when Kaori tells her the novel deeply moved her. Kaori wishes to read more of her stories, but as Shizuku did not plan on writing anything else, she has no idea what to write. As a result, Kaori comes up with a bizarre suggestion—their love. Shizuku is skeptical of Kaori''s intention and somewhat uneasy about what secrets she may be hiding behind her smile. Nevertheless, the two begin their odd summer vacation in pursuit of their own love story.',1,3,2,112,1,N'ad892471-96a5-47bc-969c-dbf986b8a3e5',NULL,'2026-04-27 17:00:00.000',N'00000000-0000-0000-0000-000000000001');
